def save_checkpoint(result, path):
    Path(path).write_text(json.dumps(result.to_dict(), indent=2))

def replay(prefix, adapter):
    return adapter.next_action(list(prefix))

for k in range(len(result.trace)):
    assert replay(result.trace[:k], DeterministicModelAdapter()) == result.trace[k]['action']

