def audit_run(result):
    v = []
    last = result.trace[-1] if result.trace else {}
    if result.steps > 6: v.append('steps_exceed_budget')
    if result.retries > 3: v.append('retries_exceed_bound')
    ok_last = last.get('observation', {}).get('ok') and last.get('action', {}).get('name') == 'write_report'
    derived = 'completed' if ok_last else ('failed' if result.retries > 2 else 'budget_exhausted')
    if derived != result.status: v.append(f'status_mismatch:{derived}')
    return {'steps': result.steps, 'retries': result.retries,
            'status': result.status, 'termination': result.termination, 'violations': v}
